package main

import (
	"fmt"
	"log"
	"net/http"
	"strings"
)

type failureText struct {
	Text string
	Step string
}

type failure struct {
	Error string `json:"error"`
	Code  string `json:"code"`
	Step  string `json:"step,omitempty"`
}

func newFailure(code string, args ...any) failure {
	t, ok := failureTexts[code]
	if !ok {
		log.Printf("failure code %q has no text", code)
		return failure{Error: strings.ReplaceAll(code, "_", " "), Code: code}
	}
	return failure{Error: fmt.Sprintf(t.Text, args...), Code: code, Step: t.Step}
}

func fail(w http.ResponseWriter, status int, code string, args ...any) {
	writeJSON(w, status, newFailure(code, args...))
}

